-- The class itself. INSERT ... WHERE NOT EXISTS rather than INSERT OR IGNORE,
-- so re-running the script is a no-op instead of a silent partial write.
INSERT INTO imported_classes (class_id, name, system, markdown, status, created_by)
SELECT 'imperial-security-agent', 'Imperial Security Agent', 'rifts', '---
id: imperial-security-agent
name: Imperial Security Agent
system: rifts
category: occ
occ_group: optional
source_book: Rifts Dimension Book 2: Phase World p.82-83
attribute_requirements: { IQ: 10, ME: 10, PE: 10 }
starting_money: "4d6x1000"
xp_table: [0, 2101, 4201, 8401, 17201, 25401, 35801, 51001, 71201, 96401, 131601, 181801, 232001, 282201, 342401]
bonuses:
